@OptIn(ExperimentalCoroutinesApi::class) class InboxLinkLeadTest {
    private fun fixture(n:String)=javaClass.classLoader!!.getResourceAsStream("fixtures/$n.json")!!.bufferedReader().use {it.readText()}
    private fun context(o:JSONObject)=InboxConversationFilesContext(o.getInt("business"),o.getInt("conversation"),o.getInt("epoch"),o.getInt("revision"))
    private fun leads()=APILeadReadRepository(ReadTransport {FixtureLeadReadTransport.response(fixture("lead-read"),it)})
    private fun source()=APIInboxLinkLeadRepository(FixtureInboxLinkLeadReadTransport.fromJSON(fixture("inbox-link-lead")))
    private fun files()=APIInboxConversationFilesRepository(FixtureInboxConversationFilesTransport.fromJSON(fixture("inbox-conversation-files")))
    private suspend fun reference(c:InboxConversationFilesContext,id:Int=3701):QualifiedLeadReference {val s=LeadReadSession();s.bind(c);s.show();s.update(" e\u0301 ",s.input);val t=s.beginList(s.control)!!;s.accept(leads().leads(c.business,t.query),t);val pt=s.beginProfile(id,s.control)!!;s.accept(leads().lead(c.business,id),pt);s.use(s.control);return s.state.choice!!}
    private suspend fun choose(p:LeadReferenceModel,id:Int){if(p.state.selectedID!=null)p.back(p.control);p.clear(p.control);p.search(p.control);p.open(id,p.control);p.use(p.control)}
    private class Held(override val grants:List<SyntheticInboxLinkLeadGrant>):SyntheticInboxLinkLeadPort {val attempts=mutableListOf<InboxLinkLeadAttempt>();val pending=mutableListOf<CompletableDeferred<SyntheticInboxLinkLeadOutcome>>();override suspend fun execute(a:InboxLinkLeadAttempt):SyntheticInboxLinkLeadOutcome {attempts+=a;return withContext(NonCancellable){CompletableDeferred<SyntheticInboxLinkLeadOutcome>().also {pending+=it}.await()}}}
    @Test fun genericSourceQualifiedScopeTwoGrantsConditionalClientReceiptBodyAndUnknown()=runTest {
        val d=JSONObject(fixture("inbox-link-lead"));val f=FixtureInboxLinkLeadPort.fromJSON(fixture("inbox-link-lead"));val cases=d.getJSONArray("source_cases")
        for(i in 0 until cases.length()){val x=cases.getJSONObject(i);assertEquals(x.getString("name"),x.getBoolean("valid"),InboxLinkLeadSource.decode(x.getString("response_json"),context(x.getJSONObject("context")))!=null)}
        val c=context(d.getJSONObject("context"));val s=InboxLinkLeadSource.decode(d.getString("source_json"),c)!!;val scopes=d.getJSONArray("candidate_scope_cases")
        for(i in 0 until scopes.length()){val x=scopes.getJSONObject(i);val ref=context(x.getJSONObject("context"));assertEquals(x.getString("name"),x.getBoolean("valid"),InboxLinkLeadCandidate.make(s,reference(ref,if(ref.business==101)3701 else 4701))!=null)}
        suspend fun review(c:InboxConversationFilesContext,raw:String):InboxLinkLeadReview {val source=InboxLinkLeadSource.decode(raw,c)!!;return InboxLinkLeadReview(source,f.grants.mapNotNull {it.authorization(c)}.first(),InboxLinkLeadCandidate.make(source,reference(c))!!,1)}
        val receipts=d.getJSONArray("receipt_cases");for(i in 0 until receipts.length()){val x=receipts.getJSONObject(i);val r=review(context(x.getJSONObject("source_context")),x.getString("source_json"));val l=InboxLinkLeadLedger();val a=l.begin(r)!!;assertEquals(x.getString("name"),x.getBoolean("valid"),InboxLinkLeadReceipt.decode(x.getString("response_json"),a)!=null)}
        val r=review(c,d.getString("source_json"));val auth=r.authorization;val l=InboxLinkLeadLedger();val a=l.begin(r)!!;val body=JSONObject(a.preparedBody());assertEquals(setOf("lead_id"),body.keys().asSequence().toSet());assertEquals(3701,body.getInt("lead_id"));assertEquals("/api/inbox/conversations/901/link-lead/",a.path);assertTrue(a.query.isEmpty());assertTrue(a.headers.isEmpty());assertNull(l.begin(r));assertFalse(l.acknowledge(auth,l.visible(auth)!!));l.complete(a,f.execute(a));val known=l.visible(auth)!!;assertEquals(InboxLinkLeadPhase.RESPONSE,known.phase);assertEquals(3701,known.result!!.source.lead);assertEquals(701,known.result!!.source.client);assertEquals(81,known.attempt.review.source.lead);assertEquals(1701,known.attempt.review.candidate.reference.detail.lead.client_id);assertTrue(l.acknowledge(auth,known))
        val nr=review(context(d.getJSONObject("null_context")),d.getString("null_source_json"));val nl=InboxLinkLeadLedger();val na=nl.begin(nr)!!;nl.complete(na,f.execute(na));assertEquals(1701,nl.visible(nr.authorization)!!.result!!.source.client);assertNull(nr.source.client)
        val u=l.begin(r)!!;l.complete(u,SyntheticInboxLinkLeadOutcome.Unknown);val unknown=l.visible(auth)!!;val next=c.copy(epoch=2,revision=2);val matching=InboxLinkLeadSource.decode(JSONObject().put("id",901).put("business",101).put("lead",3701).put("client",701).put("updated_at","matching GET").toString(),next)!!;val nAuth=f.grants[0].authorization(next)!!;assertEquals(unknown,l.visible(nAuth));assertFalse(l.acknowledge(nAuth,unknown));assertNull(l.begin(InboxLinkLeadReview(matching,nAuth,InboxLinkLeadCandidate.make(matching,reference(next))!!,2)));assertEquals(u,l.records[1].attempt);assertEquals(" e\u0301 ",unknown.attempt.review.candidate.reference.rawQuery)
        for(g in listOf(SyntheticInboxLinkLeadGrant(101,901,5001,false,true),SyntheticInboxLinkLeadGrant(101,901,5001,true,false),SyntheticInboxLinkLeadGrant(101,902,5001,true,true),SyntheticInboxLinkLeadGrant(101,901,0,true,true)))assertNull(g.authorization(c))
        val invalidRef=reference(c).copy(readRevision=0);assertNull(InboxLinkLeadCandidate.make(s,invalidRef));val other=SyntheticInboxLinkLeadGrant(101,901,6002,true,true).authorization(next)!!;assertNull(l.visible(other));assertTrue(l.blocked(101,901));assertFalse(l.blocked(202,951))
    }
    private inner class Reads:InboxRepository {override suspend fun inbox(business:Int)=JsonContracts.inbox(fixture("inbox-$business"));override suspend fun thread(business:Int,id:Int)=JsonContracts.thread(fixture("inbox-$business-$id"))}
    @Test fun actualParentFrozenPickerPendingKnownUnknownAndBusinessABA()=runTest {
        Dispatchers.setMain(StandardTestDispatcher(testScheduler));val f=FixtureInboxLinkLeadPort.fromJSON(fixture("inbox-link-lead"));val held=Held(f.grants);val m=InboxViewModel(Reads(),files=files(),leads=leads(),leadLinkRead=source(),leadLinkSubmission=held)
        try {m.load(101,560);runCurrent();m.open(901);runCurrent();val original=m.state.thread;val container=m.fileMetadata!!;val link=container.linkLead!!;val p=container.leadReference!!;m.openFiles(m.filesEntryControl);assertNull(link.source);assertFalse(p.state.loaded);link.load(link.control);val old=link.control;p.search(p.control);p.open(3701,p.control);link.prepare(link.control);assertNull(link.review);p.use(p.control);link.prepare(old);assertNull(link.review);assertTrue(link.canPrepare);link.prepare(link.control);val r=link.review;val frozen=p.state.choice;assertTrue(link.canSubmit);p.clearChoice(p.control);p.back(p.control);p.search(p.control);link.load(link.control);container.preparePriority(container.control);container.prepareLifecycle(InboxLifecycleAction.CLOSE,container.control);assertEquals(r,link.review);assertEquals(frozen,p.state.choice);assertTrue(link.canSubmit);assertNull(container.priorityReview);assertNull(container.lifecycleReview);link.back(link.control);assertFalse(p.controlsBlocked());link.prepare(link.control);val control=link.control;val job=launch {link.submit(control)};runCurrent();val pending=link.record!!;link.submit(link.control);link.acknowledge(pending,link.control);assertEquals(1,held.attempts.size);assertTrue(m.conversationCommandsBlocked);assertTrue(p.controlsBlocked());m.closeFiles(m.filesPresentationControl);m.openFiles(m.filesEntryControl);held.pending[0].complete(f.execute(held.attempts[0]));job.join();val response=link.record!!;assertEquals(InboxLinkLeadPhase.RESPONSE,response.phase);assertEquals(701,response.result!!.source.client);assertEquals(3701,response.result!!.source.lead);assertEquals(original,m.state.thread);link.acknowledge(response,control);assertEquals(response,link.record);link.acknowledge(response,link.control);assertNull(link.source);assertNull(p.state.choice);assertEquals(1,link.retainedAttemptCount);assertFalse(m.conversationCommandsBlocked)
            link.load(link.control);choose(p,3702);link.prepare(link.control);val unknownJob=launch {link.submit(link.control)};runCurrent();held.pending[1].completeExceptionally(IllegalStateException("synthetic unknown"));unknownJob.join();val unknown=link.record!!;link.load(link.control);link.acknowledge(unknown,link.control);choose(p,3701);link.prepare(link.control);assertEquals(InboxLinkLeadPhase.UNKNOWN,unknown.phase);assertEquals(3702,unknown.attempt.review.candidate.reference.detail.lead.id);assertEquals(unknown,link.record);assertNull(link.review);assertFalse(link.canPrepare);m.closeFiles(m.filesPresentationControl);m.load(202,561);runCurrent();m.open(951);runCurrent();m.openFiles(m.filesEntryControl);assertEquals("",p.state.query);assertNull(link.record);m.closeFiles(m.filesPresentationControl);m.load(101,562);runCurrent();m.open(901);runCurrent();m.openFiles(m.filesEntryControl);link.load(link.control);assertEquals(unknown,link.record);assertTrue(m.conversationCommandsBlocked)
        }finally{Dispatchers.resetMain()}
    }
    @Test fun nullClientNoTwoGrantsCancellationAndLateForeignOwner()=runTest {
        val f=FixtureInboxLinkLeadPort.fromJSON(fixture("inbox-link-lead"));val a=InboxConversationFilesContext(101,901,563,1);val b=InboxConversationFilesContext(202,951,564,1)
        suspend fun ready(c:InboxConversationFilesContext,port:SyntheticInboxLinkLeadPort):InboxLinkLeadModel {val p=LeadReferenceModel(leads());p.bind(c);p.show();val m=InboxLinkLeadModel(source(),p,port);m.commandsBlocked={false};m.bind(c);m.show();m.load(m.control);choose(p,3701);return m}
        val nullModel=ready(a.copy(conversation=902),f);nullModel.prepare(nullModel.control);nullModel.submit(nullModel.control);assertEquals(1701,nullModel.record!!.result!!.source.client);assertNull(nullModel.record!!.attempt.review.source.client)
        for(grants in listOf(emptyList(),listOf(SyntheticInboxLinkLeadGrant(101,901,5001,false,true)),listOf(SyntheticInboxLinkLeadGrant(101,901,5001,true,false)))){val m=ready(a,Held(grants));assertNotNull(m.picker!!.state.choice);m.prepare(m.control);assertNull(m.review);assertEquals(0,m.retainedAttemptCount)}
        val cp=Held(f.grants);val cancel=ready(a,cp);cancel.prepare(cancel.control);val cj=launch {cancel.submit(cancel.control)};runCurrent();cj.cancel();cp.pending[0].complete(f.execute(cp.attempts[0]));cj.join();assertEquals(InboxLinkLeadPhase.UNKNOWN,cancel.record!!.phase);assertEquals(cp.attempts[0],cancel.record!!.attempt)
        val lp=Held(f.grants);val late=ready(a,lp);late.prepare(late.control);val lj=launch {late.submit(late.control)};runCurrent();late.hide();late.picker!!.bind(b);late.picker!!.show();late.bind(b);late.show();late.load(late.control);late.picker!!.update(" B raw e\u0301 ",late.picker!!.input);val before=late.control;lp.pending[0].complete(f.execute(lp.attempts[0]));lj.join();assertEquals(before,late.control);assertEquals(" B raw e\u0301 ",late.picker!!.state.query);assertNull(late.record);assertEquals(1,late.retainedAttemptCount)
    }
    @Test fun twoLinkCommandsShareRetainedUnknownBarrierBothDirections()=runTest {
        val c=InboxConversationFilesContext(101,901,570,1);val f=FixtureInboxLinkLeadPort.fromJSON(fixture("inbox-link-lead"));val clientFixture=FixtureInboxLinkClientPort.fromJSON(fixture("inbox-link-client"));val held=Held(f.grants)
        val clientReads=object:ClientSearchRepository {override suspend fun searchClients(business:Int,search:String)=JsonContracts.clients(FixtureClientSearch.list(fixture("client-search-catalogue-$business"),business,search).body);override suspend fun clientProfile(business:Int,id:Int)=JsonContracts.clientProfile(FixtureClientSearch.profile(fixture("client-search-catalogue-$business"),business,id).body)}
        val container=InboxConversationFilesModel(files(),linkRead=APIInboxLinkClientRepository(FixtureInboxLinkClientReadTransport.fromJSON(fixture("inbox-link-client"))),linkClients=clientReads,linkPort=clientFixture,ownerScope=this,leads=leads(),leadLinkRead=source(),leadLinkPort=held);container.commandsBlocked={false};container.bind(c);container.open(container.control);val lead=container.linkLead!!;val p=container.leadReference!!;lead.load(lead.control);choose(p,3701);lead.prepare(lead.control);val client=container.linkClient!!;client.load(client.control);client.open(client.control);assertFalse(client.canOpen);val job=launch {lead.submit(lead.control)};runCurrent();held.pending[0].complete(SyntheticInboxLinkLeadOutcome.Unknown);job.join();client.load(client.control);client.open(client.control);assertFalse(client.canOpen);assertTrue(container.blocksCommands(101,901))
        val unknownClient=object:SyntheticInboxLinkClientPort {override val grants=clientFixture.grants;override suspend fun execute(a:InboxLinkClientAttempt)=SyntheticInboxLinkClientOutcome.Unknown}
        val reverse=InboxConversationFilesModel(files(),linkRead=APIInboxLinkClientRepository(FixtureInboxLinkClientReadTransport.fromJSON(fixture("inbox-link-client"))),linkClients=clientReads,linkPort=unknownClient,ownerScope=this,leads=leads(),leadLinkRead=source(),leadLinkPort=f);reverse.commandsBlocked={false};reverse.bind(c);reverse.open(reverse.control);val cl=reverse.linkClient!!;cl.load(cl.control);cl.open(cl.control);cl.update("Synthetic Beyond directory",cl.input);cl.search(cl.control,cl.picker!!.control);runCurrent();assertEquals(listOf(1701),cl.picker!!.state.items.map {it.id});cl.openClient(1701,cl.control,cl.picker!!.control);runCurrent();assertNotNull("Current profile1701",cl.picker!!.profile.readSelection);cl.useClient(cl.control,cl.picker!!.control);assertNotNull("Explicit candidate1701",cl.candidate);assertTrue(cl.canPrepare);cl.prepare(cl.control);assertNotNull("Prepared review1701",cl.review);assertTrue(cl.canSubmit);cl.submit(cl.control);assertEquals(InboxLinkClientPhase.UNKNOWN,cl.record?.phase);assertEquals(InboxLinkClientPhase.UNKNOWN,cl.record!!.phase);val ll=reverse.linkLead!!;ll.load(ll.control);choose(reverse.leadReference!!,3701);ll.prepare(ll.control);assertNull(ll.review);assertFalse(ll.canPrepare);assertTrue(reverse.blocksCommands(101,901))
    }
}
